class Solution:
    def maxScore(self, a: List[int], b: List[int]) -> int:
        NEG = float('-inf')
        dp = [0, NEG, NEG, NEG]
        for x in b:
            for k in range(3, 0, -1):
                if dp[k-1] != NEG:
                    dp[k] = max(dp[k], dp[k-1] + a[k] * x)
            dp[0] = max(dp[0], a[0] * x)
        return dp[3]

