class Solution {
public:
    long long maxScore(vector<int>& a, vector<int>& b) {
        const long long NEG = LLONG_MIN / 2;
        vector<long long> dp = {0, NEG, NEG, NEG};
        for (int x : b) {
            for (int k = 3; k >= 1; k--)
                dp[k] = max(dp[k], dp[k-1] + (long long)a[k] * x);
            dp[0] = max(dp[0], (long long)a[0] * x);
        }
        return dp[3];
    }
};

