class Solution:
    def maxScore(self, a: List[int], b: List[int]) -> int:
        import sys
        from functools import lru_cache
        sys.setrecursionlimit(400000)
        n = len(b)
        @lru_cache(maxsize=None)
        def f(j, k):
            if k == 4: return 0
            if n - j < 4 - k: return float('-inf')
            return max(f(j+1, k), a[k] * b[j] + f(j+1, k+1))
        return f(0, 0)

