class Solution {
    vector<vector<long long>> memo;
    vector<int> a, b;
    long long f(int j, int k) {
        if (k == 4) return 0;
        if ((int)b.size() - j < 4 - k) return LLONG_MIN / 2;
        long long &m = memo[j][k];
        if (m != LLONG_MIN) return m;
        m = max(f(j+1, k), (long long)a[k] * b[j] + f(j+1, k+1));
        return m;
    }
public:
    long long maxScore(vector<int>& a_, vector<int>& b_) {
        a = a_; b = b_;
        memo.assign(b.size(), vector<long long>(4, LLONG_MIN));
        return f(0, 0);
    }
};

