class Solution {
    Long[][] memo;
    int[] a, b;
    long f(int j, int k) {
        if (k == 4) return 0;
        if (b.length - j < 4 - k) return Long.MIN_VALUE / 2;
        if (memo[j][k] != null) return memo[j][k];
        return memo[j][k] = Math.max(f(j+1, k), (long)a[k] * b[j] + f(j+1, k+1));
    }
    public long maxScore(int[] a_, int[] b_) {
        a = a_; b = b_;
        memo = new Long[b.length][4];
        return f(0, 0);
    }
}

